import os
from google.cloud import monitoring_v3

def filter_metric_dimensions(payload, config=None):
    config = config or {}
    client = monitoring_v3.MetricServiceClient()
    result = {}
    for item in payload.get("items", []):
        project_id = item.get("project_id") or config.get("project_id") or os.getenv("GOOGLE_CLOUD_PROJECT")
        if not project_id:
            continue
        filter_parts = []
        metric_type = item.get("metric_type") or config.get("metric_type")
        if metric_type:
            filter_parts.append(f'metric.type = "{metric_type}"')
        resource_type = item.get("resource_type") or config.get("resource_type")
        if resource_type:
            filter_parts.append(f'resource.type = "{resource_type}"')
        for k, v in (item.get("labels") or {}).items():
            filter_parts.append(f'metric.labels.{k} = "{v}"')
        for k, v in (item.get("resource_labels") or {}).items():
            filter_parts.append(f'resource.labels.{k} = "{v}"')
        filter_str = " AND ".join(filter_parts) if filter_parts else ""
        name = f"projects/{project_id}"
        query = monitoring_v3.ListTimeSeriesRequest(
            name=name,
            filter=filter_str,
            interval=monitoring_v3.TimeInterval(
                end_time={"seconds": int(item.get("end_time", 0) or 0)},
                start_time={"seconds": int(item.get("start_time", 0) or 0)},
            ) if item.get("start_time") or item.get("end_time") else None,
        )
        series = []
        for ts in client.list_time_series(request=query):
            series.append(
                {
                    "metric": dict(ts.metric.labels),
                    "resource": dict(ts.resource.labels),
                    "points": [
                        {
                            "value": p.value.to_json() if hasattr(p.value, "to_json") else str(p.value),
                            "timestamp": p.interval.end_time.isoformat(),
                        }
                        for p in ts.points
                    ],
                }
            )
        result[item.get("name") or project_id] = series
    return result
